SELECT 
FROM sys_schedule_item
WHERE deleted = 0
  AND NOT (
    item_type = 'TASK'
    AND start_at IS NULL
    AND end_at IS NULL
    AND due_at IS NULL
  )
  AND COALESCE(start_at, end_at, due_at) IS NOT NULL
  AND COALESCE(start_at, end_at, due_at) <= #{endDate}
  AND COALESCE(end_at, start_at, due_at) >= #{startDate}

    AND item_type = #{itemType}


    AND status = #{status}


    AND priority = #{priority}


    AND category_id = #{categoryId}


    AND (
      title LIKE CONCAT('%', #{keyword}, '%')
      OR IFNULL(description, '') LIKE CONCAT('%', #{keyword}, '%')
      OR IFNULL(location, '') LIKE CONCAT('%', #{keyword}, '%')
    )

ORDER BY
    CASE priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END,
    COALESCE(start_at, due_at, end_at) ASC,
    sort_order ASC,
    id ASC

SELECT FROM sys_schedule_item WHERE deleted = 0 AND item_type = 'TASK' AND start_at IS NULL AND end_at IS NULL AND due_at IS NULL
AND status = #{status}
AND priority = #{priority}
AND category_id = #{categoryId}
AND ( title LIKE CONCAT('%', #{keyword}, '%') OR IFNULL(description, '') LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY CASE priority WHEN 'HIGH' THEN 0 WHEN 'MEDIUM' THEN 1 ELSE 2 END, sort_order ASC, create_time DESC, id DESC

